head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        const vHeadString = "ITEM:STRING(100),NEWLIST_REQ:STRING(300),EXEM_REQ:STRING(300),CORRYN:STRING(1)";
        // dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        const parentWin = $c.frame.path("../");
        const vViewCorrYnTyp = parentWin.vViewCorrYnTyp;
        const dtsObj = parentWin.dts_CorrYn;

        // setObjectValue(txb_ISU_CD, getObjectValue(parentWin.txb_ISU_CD));
        // setObjectValue(txb_ISU_KOR_NM, getObjectValue(parentWin.txb_ISU_KOR_NM));
        txb_ISU_CD.setValue(dtsObj.getCellData(1, 'ISU_CD'));
        txb_ISU_KOR_NM.setValue(dtsObj.getCellData(1, 'ISU_KOR_NM'));
        grd_List.Redraw = false;
        if (vViewCorrYnTyp === '1') {
            // 신규상장
            scwin.setListingData(dtsObj);
        } else if (vViewCorrYnTyp === '2') {
            // 추가상장
            scwin.setAddListingData(dtsObj);
        } else if (vViewCorrYnTyp === '3') {
            // 신규상장송수신
            $c.cm.setColumnProp(grd_List, "NEWLIST_REQ", "Name", '송신데이타(상장공시)');
            $c.cm.setColumnProp(grd_List, "EXEM_REQ", "Name", '수신데이타(매매)');
            scwin.setSndRcvData(dtsObj);
        }
        grd_List.redraw = true;
        dts_List.setRowPosition(1, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05903.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05903.btn_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
